typedef struct context {const fixture *value;uint32_t calls;int fail;} context;
static int query(void *p,const float point[3],uint32_t *room)
{
    context *c=p;uint32_t n=c->calls++;
    if(c->fail && n+1==(uint32_t)c->fail)return RF_FORMAT;
    if(n>=c->value->count || memcmp(point,c->value->points[n],12))return RF_RANGE;
    *room=(int)n==c->value->success ? 0u:UINT32_MAX;
    return RF_OK;
}
int main(void)
{
    uint32_t i;float radius,center[3]={10,20,30},normal[3]={0,1,0};
    rf_random_state random;rf_geomod_debris_burst_room value,before;context c;
    for(i=0;i<sizeof(cases)/sizeof(cases[0]);i++) {
        const fixture *f=cases+i;memcpy(&radius,&f->radius,4);random.value=f->seed;
        c.value=f;c.calls=0;c.fail=0;
        if(rf_geomod_debris_select_room(center,normal,radius,f->fallback,query,&c,&random,&value)) {
            fprintf(stderr,"original selection fixture %u failed at query %u\n",i,c.calls);return 1;
        }
        CHECK(random.value==f->state && c.calls==f->count && value.queries==f->count);
        CHECK(value.room==(f->success>=0 ? 0u:f->fallback));
        CHECK(value.used_fallback==(f->success<0 && f->fallback!=UINT32_MAX));
        CHECK(!memcmp(value.origin,f->success>=0 ? (const void*)f->points[f->count-1]:(const void*)center,12));
    }
    memset(&before,0xa5,sizeof(before));value=before;random.value=123;c.calls=0;c.fail=1;
    CHECK(rf_geomod_debris_select_room(center,normal,2,9,query,&c,&random,&value)==RF_FORMAT);
    CHECK(random.value==123 && !memcmp(&value,&before,sizeof(value)));
    c.value=cases;c.calls=0;c.fail=4;random.value=cases[0].seed;
    CHECK(rf_geomod_debris_select_room(center,normal,.5f,9,query,&c,&random,&value)==RF_FORMAT);
    CHECK(c.calls==4 && random.value==cases[0].seed && !memcmp(&value,&before,sizeof(value)));
    random.value=123;
    c.calls=0;CHECK(rf_geomod_debris_select_room(center,normal,0,9,query,&c,&random,&value)==RF_RANGE);
    CHECK(!c.calls && random.value==123 && !memcmp(&value,&before,sizeof(value)));
    normal[0]=NAN;CHECK(rf_geomod_debris_select_room(center,normal,2,9,query,&c,&random,&value)==RF_RANGE);
    CHECK(!c.calls && random.value==123 && !memcmp(&value,&before,sizeof(value)));
    puts("PASS 162 captured original burst-room/RNG vectors and transactional guards");return 0;
}
